<?php
declare(strict_types=1);
session_start();require_once __DIR__ . '/config/product_step11.php';if(empty($_SESSION['product_image_csrf']))$_SESSION['product_image_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['product_image_csrf'];$error=null;$success=null;$rows=[];$q=trim((string)($_GET['q']??''));
try{$pdo=business_db();product_step11_ensure($pdo);$ctx=product_org_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){$productId=(int)($_POST['product_id']??0);$url=trim((string)($_POST['image_url']??''));$page=trim((string)($_POST['source_page_url']??''));$source=trim((string)($_POST['source_name']??''));$status=(string)($_POST['verification_status']??'needs_review');if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');if($productId<=0)throw new RuntimeException('Choose a product.');if($url!==''&&!filter_var($url,FILTER_VALIDATE_URL))throw new RuntimeException('Image URL is invalid.');if($page!==''&&!filter_var($page,FILTER_VALIDATE_URL))throw new RuntimeException('Source page URL is invalid.');if(!in_array($status,['verified','needs_review','missing'],true))$status='needs_review';$pdo->beginTransaction();try{$pdo->prepare("UPDATE product_images SET is_primary=0 WHERE product_id=?")->execute([$productId]);if($url===''){$pdo->prepare("DELETE FROM product_images WHERE product_id=?")->execute([$productId]);}else{$stmt=$pdo->prepare("INSERT INTO product_images(product_id,image_url,source_page_url,source_name,verification_status,verified_at,alt_text,is_primary,sort_order) SELECT id,?,?,?,?,?,product_name,1,0 FROM products WHERE organization_id=? AND id=?");$stmt->execute([$url,$page?:null,$source?:'Manual reviewed source',$status,$status==='verified'?date('Y-m-d H:i:s'):null,$orgId,$productId]);if($stmt->rowCount()!==1)throw new RuntimeException('Product image could not be linked.');}if(business_table_exists($pdo,'audit_logs')){$a=$pdo->prepare("INSERT INTO audit_logs(organization_id,event_type,entity_type,entity_id,details_json) VALUES(?,'product_image_updated','product',?,?)");$a->execute([$orgId,$productId,json_encode(['status'=>$status,'source_name'=>$source,'source_page_url'=>$page],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)]);}$pdo->commit();$success='Product image state updated.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
$sql="SELECT p.id,p.sku,p.product_name,c.category_name,pi.image_url,pi.source_page_url,pi.source_name,pi.verification_status FROM products p LEFT JOIN product_categories c ON c.id=p.category_id LEFT JOIN product_images pi ON pi.id=(SELECT pi2.id FROM product_images pi2 WHERE pi2.product_id=p.id ORDER BY pi2.is_primary DESC,pi2.sort_order,pi2.id DESC LIMIT 1) WHERE p.organization_id=?";$args=[$orgId];if($q!==''){$sql.=" AND (p.product_name LIKE ? OR p.sku LIKE ?)";$like='%'.$q.'%';$args[]=$like;$args[]=$like;}$sql.=" ORDER BY c.sort_order,p.product_name";$stmt=$pdo->prepare($sql);$stmt->execute($args);$rows=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function pim_img(array $r):string{return $r['image_url']?:('product_placeholder.php?'.http_build_query(['name'=>$r['product_name'],'stock'=>$r['sku'],'cat'=>$r['category_name']]));}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Product Image Manager - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="product_catalog.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>Product & Price Pro • Image Verification</small></span></a><div class="os-top-actions"><a class="os-btn" href="product_catalog.php">Catalog</a><a class="os-btn primary" href="product_audit.php">STEP 11 Audit</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Product System</div><nav class="os-nav"><a href="product_catalog.php"><i class="dot"></i>Catalog</a><a class="active" href="product_images.php"><i class="dot"></i>Image Manager</a><a href="product_data_center.php"><i class="dot"></i>Data Center</a><a href="product_price_history.php"><i class="dot"></i>Price History</a><a href="product_order_builder.php"><i class="dot"></i>Order Builder</a></nav><div class="os-sidebar-status"><b>Wrong-image protection</b><span>Online images remain NEEDS REVIEW until the product/pack match is checked. Missing images keep a local placeholder.</span></div></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 11 • Product Images</div><h1>Keep product imagery useful without silently attaching a wrong pack or flavour.</h1><p>Online matches can be reviewed, replaced or removed. Every product always has visual coverage through a local placeholder, while verified image sources remain separately traceable.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'IMAGE MANAGER LIVE':'Review required' ?></span><span class="os-chip"><?= number_format(count($rows)) ?> products</span></div></section><?php if($success):?><div class="pp-alert good"><?= product_h($success) ?></div><?php endif;?><?php if($error):?><div class="pp-alert bad"><?= product_h($error) ?></div><?php endif;?><?php if(!$error):?><section class="os-card" style="margin-top:14px"><form method="get" class="pp-toolbar" style="grid-template-columns:1fr auto"><input name="q" value="<?= product_h($q) ?>" placeholder="Search product / Stock No."><button>Search</button></form></section><section class="pp-image-grid"><?php foreach($rows as $r):$status=$r['image_url']?($r['verification_status']?:'needs_review'):'missing';?><article class="pp-image-card"><img src="<?= product_h(pim_img($r)) ?>" alt="<?= product_h($r['product_name']) ?>" onerror="this.src='<?= product_h('product_placeholder.php?'.http_build_query(['name'=>$r['product_name'],'stock'=>$r['sku'],'cat'=>$r['category_name']])) ?>'"><h3><?= product_h($r['sku'].' • '.$r['product_name']) ?></h3><p><?= product_h($r['category_name']) ?> • <?= product_h(strtoupper(str_replace('_',' ',$status))) ?></p><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= product_h($csrf) ?>"><input type="hidden" name="product_id" value="<?= (int)$r['id'] ?>"><label>Image URL<input name="image_url" value="<?= product_h($r['image_url']) ?>" placeholder="https://…"></label><label>Source Page URL<input name="source_page_url" value="<?= product_h($r['source_page_url']) ?>" placeholder="https://…"></label><label>Source Name<input name="source_name" value="<?= product_h($r['source_name']) ?>" placeholder="Official / retailer reference"></label><label>Status<select name="verification_status"><option value="needs_review" <?= $status==='needs_review'?'selected':'' ?>>Needs review</option><option value="verified" <?= $status==='verified'?'selected':'' ?>>Verified</option><option value="missing" <?= $status==='missing'?'selected':'' ?>>Missing / placeholder</option></select></label><button>Save Image State</button></form></article><?php endforeach;?></section><?php endif;?></main></div></body></html>